WHO = {'column': [('aprilro', 82882), ('unelwei', 83074), ('muut', 0), ('orgdmfools', 83266), ('orgdmolsof', 83842), ('einsof', 83842), ('aprilylglo', 83842), ('mueocero', 83842)], 'tree': [('weitflcero', 0), ('elghaun', 84802), ('aprilro', 0), ('aprilcero', 85762), ('elghaun', 0), ('elghaun', 87874), ('aprilfools', 88386), ('elghaun', 0)], 'bridge': [('uneloicro', 83138), ('orgdmdmicro', 83906), ('alphafoldmicro', 84098), ('muehaun', 0), ('orgdmhaun', 87170), ('alphafoldmicro', 0), ('aprilmhaun', 0), ('alphafoldmicro', 87234)], 'temple': [('kiro', 83842), ('aprillgepy', 0), ('psilocero', 90498), ('kiro', 0), ('rofyomumae', 95106)], 'tower': [('psilocero', 0), ('musof', 85058), ('mumcooumae', 86978), ('qudmicro', 90306), ('orgdmolum', 0), ('mugelcdmicro', 0), ('bridgepy', 90818), ('weitfolsof', 90818)], 'manor': [('orgdmgepy', 87426), ('weitflcero', 88258), ('kiccgepy', 89346), ('orgdmgepy', 89346), ('rofyodmicro', 89346), ('ortecdmicro', 0), ('kiylglo', 0), ('kiylmgepy', 93826)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW122(OracleReleaseRuntimeW117):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
